41	    let rows = match crate::db::firehose_seq::recent_commits_for_did(&state.db, did, 200).await {
42	        Ok(rows) => rows,
43	        Err(err) => {
44	            tracing::error!(error = %err, did, "failed to fetch recent commits");
45	            return LocalRecords::default();
46	        }
47	    };
48	
49	    // 2. Decode each row and walk newest-first, stopping at rev <= header_rev.
50	    // Collect distinct (collection, rkey), keeping the newest CommitEvent.time per key.
51	    let mut touched: HashMap<(String, String), (String, Cid)> = HashMap::new(); // (coll, rkey) -> (time, cid)
52	
53	    for row in rows {
54	        let event = match crate::firehose::decode_stored_event(
55	            row.seq as u64,
56	            &row.event_type,
57	            &row.event,
58	        ) {
59	            Ok(crate::firehose::FirehoseEvent::Commit(c)) => c,
60	            Ok(_) => continue, // Should not happen; we filtered for 'commit' in the query
61	            Err(err) => {
62	                tracing::debug!(error = %err, seq = row.seq, "failed to decode commit event");
63	                continue; // best-effort: skip this record
64	            }
65	        };
66	
67	        // Stop if this commit's rev is at or below the header rev (string comparison: TIDs sort by time)
68	        if event.rev.as_str() <= header_rev {
69	            break;
70	        }
71	
72	        // Collect ops from this commit
73	        for op in &event.ops {
74	            let key = (op.collection.clone(), op.rkey.clone());
75	            // Keep the first (newest) occurrence since we're walking newest-first
76	            if let std::collections::hash_map::Entry::Vacant(e) = touched.entry(key) {
77	                if let Some(cid_str) = &op.cid {
78	                    if let Ok(cid) = Cid::try_from(cid_str.as_str()) {
